{ "laser": 483, "lander": 206, "mutant": 196, "dynamo": 164, "firebomber": 161, "hum": 140,
       "ground color": 143, "men": 123, "bomber color": 98, "turn": 91, "shot color": 82, "laser color": 81, "flame": 77,
       "director": 432, "boom": 414, "gate trip": 247, "death": 540, "swarmer": 228, "pod boom": 331, "yllabian": 231, "bombers": 136, "ghost": 278, "smart bomb": 90, "inviso": 224 }

{ "director/start": 100000, "director/muster": 38400, "dynamo/arrive": 430, "firebomber/arrive": 494,
       "gate trip/dim": 33300, "gate trip/brighten": 1400, "gate trip/enter": 1400,
       "death/burstOver": 20000, "death/burst": 4600,
       // a ship's start: the playfield cleared four pixel pairs at a time, the world emptied; then the
       // planet and ship set up, the top of the screen cleared and drawn again, the playfield cleared again
       "death/clearing": 1400, "director/clearing": 1400, "death/emptied": 11000, "director/emptied": 11000,
       "page/titleDark": 94000,         // the title page's clearing of the whole screen
       "director/clearPanel": 25000, "director/drawPanel": 10000, "director/clearAgain": 68200, "director/land": 14600,
       "pod countdown/convention": 3600, "pod countdown/countdown": 1100, "swarmer/aim": 96,
       "hyperspace/arrive": 141000, "hyperspace/back": 1250, "smart bomb/over": 59900, "inviso/check": 5800, "inviso/count": 1450 }

methods.body:
while (this.spare > 0) {
    if (this.clearAfterLongTurn) { this.framesWaiting = 0; this.clearAfterLongTurn = false }
    if (this.stage == "idle") {
        if (this.framesWaiting == 0) { this.spare = 0; return }
        this.advance(w, "done", 0, false)
        this.beginPass(w, this.framesWaiting)
        this.framesWaiting = 0
        }
    this.spare = this.spare - this.nextPiece(w)
    }

const near = w.near.length
if (this.stage == "touching") { this.advance(w, "effects", 0, false); return 293 }
if (this.stage == "effects") {
    const effects = w.appears.length + w.bursts.length, blocks = this.effectBlocks(w)
    this.advance(w, "chance", 0, false)
    return 100 + 508 * effects + 43 * blocks
    }
if (stageAt(this.stage) < stageAt("turns")) { this.advance(w, "turns", 0, false); return 191 }
if (this.turn >= w.turns.length) { this.nextTurn(w); return 0 }
const t = w.turns[this.turn]
if (t.wait != 1) { this.nextTurn(w); return 18 }
const kind = t.kind, step = t.step, far = w.far.length, shells = w.shots.length, bursts = w.bursts.length
this.nextTurn(w)
const started = Math.max(0, w.bursts.length - bursts)
if (kind == "director" && (step == "land" || step == "muster")) this.clearAfterLongTurn = true
if (kind == "scanner") return step == "far" ? 98 + 113 * far : step == "near" ? 76 + 46 * near + 24 * shells
    : step == "show" ? 2400 : 578 + 78 * (near + far)
if (kind == "laser") return 357 + 23 * near + 4730 * started
return this.longTurns[kind + "/" + step] ?? this.turnCosts[kind] ?? 128

const g = w.seen, shipRow = w.ship.py, below = w.near.filter((t) => t.py > this.split).length
const groundDrawn = g.groundShown && !this.isOff("planet")      // (not while the planet is stopped)
return 442 + (groundDrawn ? 4410 : 0) + (this.frozen() ? 0 : 391 + 98 * w.near.length + 335 * below)
    + (g.shipShown && shipRow > this.split ? 762 : 0) + (Math.floor(g.scroll / 4) != Math.floor(g.lastScroll / 4) ? 378 : 0)

const g = w.seen, shipRow = w.ship.py, above = w.near.filter((t) => t.py != 0 && t.py <= this.split).length
return 540 + (this.frozen() ? 0 : 519 + 53 * w.near.length + 367 * above + 132 * w.shots.length + 47 * this.starsLit())
    + (g.shipShown && shipRow <= this.split ? 701 : 0) + (Math.floor(g.scroll / 4) != Math.floor(g.lastScroll / 4) ? 146 : 0)

while (this.stage != "idle" && stageAt(this.stage) < stageAt("turns") && stageAt(this.stage) < stageAt(to)) {
    if (this.stage == "touching") this.touchShip(w)
    else if (this.stage == "effects") this.updateEffects(w)
    else if (this.stage == "chance") this.drawLots(w)
    else { this.takePresses(w); this.turn = 0 }
    this.stage = STAGES[stageAt(this.stage) + 1]
    }
if (this.stage != "turns" || stageAt(to) < stageAt("turns")) return
if (to == "turns") {
    while (this.stage == "turns" && this.turn < index) this.nextTurn(w)
    if (done && this.stage == "turns" && this.turn == index) { this.nextTurn(w); while (this.goesOn && this.stage == "turns" && this.turn == index) this.nextTurn(w) }
    }
else while (this.stage == "turns") this.nextTurn(w)

for (const t of w.turns) if (!keep.includes(t)) this.memory.givePlace(t)
w.turns = w.turns.filter((t) => keep.includes(t))
this.turn = keep.length == 0 ? -1 : w.turns.findIndex((t) => t.id == (from ?? keep[0]).id)

const it = this.thing(t.thing ?? 0)
switch (t.kind) {
    case "lander": case "mutant":
        if (it == null) return was
        if (it.kind == "mutant") return it.shotIn ?? was
        const man = this.thing(it.man ?? 0)
        return man != null && this.holds(man.id) ? this.pageOf(man.id) : was       // where its man is kept
    case "dynamo": case "hum": case "firebomber": return it?.course ?? was
    case "fireball": return it?.curve ?? was
    case "boom": return t.count ?? was
    case "laser": return t.beam?.fizz ?? was
    default: return was
    }

const kept = this.holds(t.thing ?? 0) ? this.pageOf(t.thing) : was
switch (t.kind) {
    case "scanner": case "notice color": return t.count ?? kept
    default: return kept
    }

if (t.place < 0) return
const left = this.leftInPlace.slice()
while (left.length < 85) left.push(255)
left[t.place] = byte(this.leaves(t, left[t.place]))
this.leftInPlace = left
const counts = this.countLeftInPlace.slice()
while (counts.length < 85) counts.push(0)
counts[t.place] = byte(this.leavesSecond(t, counts[t.place]))
this.countLeftInPlace = counts
this.places = [t.place, ...this.places]

const place = Math.floor(at / 64), i = this.effectPlaces.indexOf(place)
if (at % 64 != 1 || i < 0) return 0
const next = this.effectPlaces[i + 1]
return next == null ? 0 : 64 * next % 256        // (the low half of its address)

if (slot < 0) return
const left = this.leftInSlot.slice()
while (left.length < 95) left.push(0)
left[slot] = byte(height * 256)
this.leftInSlot = left
this.slots = [slot, ...this.slots]

let r = this.draw()
while (r > most) r = Math.floor(r / 2)
return (r + 1) % 256

const left = this.game.wrapX(this.game.scroll - 874)
const marks = []
for (const t of [...this.game.world.near, ...this.game.world.far]) {
    const inks = this.marksOf[t.kind]
    if (inks == null) continue
    const plain = ["hum", "fireball", "baiter", "man", "lander", "gate", "phony gate"].includes(t.kind)
    marks.push({ id: marks.length, px: 88 + 2 * Math.floor(this.game.wrapX(t.x - left) / 32), py: Math.floor(t.y / 8) + 3,
        inks: highlight && !plain ? [9, 9, 9, 9] : inks, gate: t.kind == "gate" || t.kind == "phony gate" })
    }
this.game.world.scan = { blips: marks, ground: this.game.planetGone ? this.game.world.scan.ground : this.scanGround(),
    shipPx: 2 * (Math.floor(this.game.world.ship.px / 32) + 71) - 1, shipPy: Math.floor(this.game.world.ship.py / 8) + 3 }

this.held = c
const down = ["fire", "smartBomb", "hyperspace", "reverse"].filter((name) => c[name])
const pressed = down.filter((name) => !this.downLast.includes(name) && !this.downBefore.includes(name))
this.downBefore = this.downLast; this.downLast = down
const places = this.waiting.slice()
for (const name of pressed) { const free = places.indexOf(""); places[free < 0 ? 3 : free] = name }
this.waiting = places

if (this.game.controlsOff) return
ship.speed = ship.speed - this.pace(ship) / 64
if (this.held.thrust) ship.speed = ship.speed + ship.facing * this.thrust
const lead = Math.floor(ship.speed * 8)
const home = (ship.facing > 0 ? 64 : 224) + (lead * ship.facing >= 0 ? lead : 0)
let slide = 0
if (home - ship.x > 2) { slide = 2; ship.x = ship.x + 2 }
else if (home - ship.x <= -2) { slide = -2; ship.x = ship.x - 2 }
else ship.x = home
const fraction = ship.speed - this.pace(ship)          // (kept when the speed is capped)
ship.speed = Math.max(fraction - 8, Math.min(fraction + 8, ship.speed))
this.game.lastScroll = this.game.scroll
this.game.scroll = this.game.wrapX(this.game.scroll + this.pace(ship) - slide)
ship.planetX = this.game.wrapX(Math.floor(ship.x) + this.game.scroll)
this.climb(ship)

if (this.held.up) {
    if (ship.y < this.game.top + 2) return
    ship.climb = ship.climb < 0 ? Math.max(ship.climb - 1 / 32, -2) : -1
    }
else if (this.held.down) {
    if (ship.y >= 238) return
    ship.climb = ship.climb > 0 ? Math.min(ship.climb + 1 / 32, 2) : 1
    }
else ship.climb = 0
ship.y = ship.y + ship.climb
ship.nextPy = Math.floor(ship.y)

if (this.game.spectacle || this.beams >= 4) { this.game.end(t); return }
this.beams = this.beams + 1
this.game.sound("laser")
const ship = this.game.world.ship, nose = Math.floor(Math.floor(ship.x) / 2) + (ship.turnTo > 0 ? 7 : 0)
t.beam = { row: Math.floor(ship.y) + 4, way: ship.turnTo > 0 ? 1 : -1, head: nose, fizz: nose, tail: nose }
this.beam(t)

t.step = "beam"
const b = t.beam, way = b.way, row = b.row, laser = this.game.ink.laser, white = this.game.ink.marks
const spent = this.game.controlsOff || (way > 0 ? b.head >= 152 : b.head < 5)
if (!spent) {
    for (let k = 0; k < 4; k++) this.mark(row, b.head + way * k, laser, laser)
    b.head = b.head + 4 * way
    this.mark(row, b.head, white, white)
    if (this.fizzleAt >= 29) this.fizzleAt = 0
    const ragged = [this.fizzle[this.fizzleAt], this.fizzle[this.fizzleAt + 1], this.fizzle[this.fizzleAt + (way > 0 ? 2 : 1)]]
    ragged.forEach((inks, k) => this.mark(row, b.fizz + k * way, inks[0], inks[1]))
    this.fizzleAt = this.fizzleAt + (way > 0 ? 3 : 2)
    b.fizz = b.fizz + 3 * way
    this.mark(row, b.tail, 0, 0)
    b.tail = b.tail + way
    if (!this.game.touch(2 * (way > 0 ? b.head - 6 : b.head), row, "laser", false)) { t.wait = 1; return }
    }
for (let p = b.tail; way > 0 ? p <= b.head : p >= b.head; p += way) this.mark(row, p, 0, 0)
this.game.world.trails = this.game.world.trails.filter((trail) => trail.inks.some((ink) => ink != 0))
this.beams = this.beams - 1
this.game.end(t)

if (pair < 0 || pair >= 160) return
let trail = this.game.world.trails.find((t) => t.id == row)
if (trail == null) {
    if (left == 0 && right == 0) return
    trail = { id: row, inks: new Array(320).fill(0) }
    this.game.world.trails.push(trail)
    }
trail.inks[2 * pair] = left
trail.inks[2 * pair + 1] = right

this.point("shell begun")
const across = this.game.across(firer.x)
this.point("shell across")
const y = Math.floor(firer.y)
if (this.inFlight >= 20 || across >= this.game.screenWidth || y <= this.game.top || this.game.memory.slots.length == 0) return null
const pair = byte(Math.floor(across / 2))
this.game.nextId = this.game.nextId + 1
const shot = { id: this.game.nextId, kind: kind, x: 2 * pair + y / 128, y: y + pair / 256, vx: 0, vy: 0,
    px: 2 * pair, py: y, life: 20, alive: true }
this.game.memory.takeSlot(shot.id)
this.point("shell placed")
this.game.world.shots.unshift(shot)
this.inFlight = this.inFlight + 1
return shot

t.count = ((t.count ?? 0) + 1) % 10
t.wait = 2
const man = this.game.thing(this.game.world.men[t.count])
if (man == null || man.py == 0 || man.state != "ground") return
const left = man.facing < 0
if (this.game.chance.last <= 8) {
    man.facing = -man.facing; man.frame = 1
    man.x = this.game.wrapX(man.x + (left ? 1 : -1))
    return
    }
const level = Math.min(232, byte(this.game.scenery.under(man.x) + (left ? 4 : 15))), y = Math.floor(man.y)
if (level != y) man.y = man.y + (level > y ? 1 : -1)
man.frame = 3 - man.frame
man.x = this.game.wrapX(man.x + (left ? -1 : 1))

if (this.game.gameOver) return
this.game.world.men[this.game.world.men.indexOf(man.id)] = 0
this.left = this.left - 1
if (this.left == 0) this.game.director.lastManGone()
else if (this.left <= 3) this.game.messages.show("few men", 0)

if (man.vy + 1 / 32 < 3) man.vy = man.vy + 1 / 32
if (this.game.scenery.under(man.x) > Math.floor(man.y)) { this.rest(t, 4, "falling"); return }
if (man.vy <= 0.875) { this.landOn(t, man, "landed"); return }
this.game.impact = { px: man.px + 2, py: man.py + 7 }
this.kill(man)
this.game.end(t)

man.vy = 0
man.y = Math.floor(this.game.world.ship.y) + 10 + man.y % 1
man.x = this.game.wrapX(this.game.world.ship.planetX + 4)
if (this.game.scenery.under(man.x) < Math.floor(man.y)) { this.carried = this.carried - 1; this.landOn(t, man, "setDown") }
else this.rest(t, 1, "hanging")

for (let k = 0; k < count; k++) {
    if (this.game.men.left == 0) { this.sendMutants(count - k); return }
    const [turn, t] = this.game.spawn("lander", "cruise")
    this.game.chance.draw()
    t.x = this.game.chance.placeOnPlanet()
    t.y = 46 + t.y % 1
    t.vy = this.drop()
    t.state = "cruising"
    t.shotIn = this.game.chance.upTo(this.settings.landerShotTime)
    const pace = this.game.chance.upTo(this.settings.landerSpeed)
    t.vx = pace % 2 == 1 ? this.game.reverseAcross(pace / 32) : pace / 32
    this.game.effects.appear(t)
    this.game.men.pick(t)
    this.out = this.out + 1
    }

const man = this.game.men.stillThere(t)
if (man == null) { this.lost(turn, t); return }
this.point("over its man?")
if (Math.floor(t.x / 32) != Math.floor(man.x / 32)) { this.glide(turn, t); return }
t.stays = true
t.vx = 0; t.vy = 0
this.seek(turn, t)

const level = byte(this.game.scenery.under(t.x) - 50), y = Math.floor(t.y)
if (level > y) t.vy = this.drop()
else t.vy = signed8(level - y) < -20 ? this.game.reverseUpDown(this.drop()) : 0
if (t.appearing || t.py == 0) { this.rest(turn, 6, "cruise"); return }
this.shoot(t)
this.nextFrame(t)
this.rest(turn, 3, "cruiseOn")

t.stays = false
if (this.game.men.pick(t)) this.glide(turn, t)
else this.becomeMutant(turn, t)

const man = this.game.men.stillThere(t)
if (man == null) { this.lost(turn, t); return }
const mine = Math.floor(t.x), his = Math.floor(man.x)
if (mine != his) t.x = this.game.wrapX(t.x + (this.game.offset(mine, his) < 0 ? 1 : -1))
const level = Math.floor(man.y) - 12, y = Math.floor(t.y)
if (level == y && this.game.wrapX(t.x + 2 - man.x) <= 4) {
    t.state = "carrying"
    t.vy = this.game.reverseUpDown(this.drop()); man.vy = t.vy
    this.game.sound("man taken")
    man.state = "taken"
    turn.step = "flee"
    this.flee(turn, t)
    return
    }
if (level != y) t.y = t.y + (level >= y ? this.drop() : this.game.reverseUpDown(this.drop()))
this.shoot(t)
this.rest(turn, 1, "seek")

if (t.y < 53) { this.game.sound("man drawn in"); turn.step = "drawIn"; this.drawIn(turn, t); return }
if (t.py != 0) { this.shoot(t); this.nextFrame(t) }
this.rest(turn, 3, "flee")

const man = this.game.thing(t.man)
if (this.game.world.men[t.listed] == 0 || man == null) {
    this.game.leave(t)
    this.out = this.out - 1
    this.game.director.count("landers", 1)
    this.game.end(turn)
    return
    }
t.vy = 0; man.vy = 0
if (Math.floor(man.y) > Math.floor(t.y)) {
    man.y = man.y - 1
    this.rest(turn, 1, "drawIn")
    return
    }
this.game.impact = { px: man.px + 2, py: man.py }
this.game.men.kill(man)
this.becomeMutant(turn, t)

if (t.kind == "mutant") { this.game.director.count("mutants", -1); this.game.destroy(t, 150, "mutant hit"); return true }
if (t.state == "carrying" && this.game.world.men[t.listed] != 0) this.game.men.drop(this.game.thing(t.man))
this.gone()
this.game.destroy(t, 150, "lander hit")
return true

for (let k = 0; k < count; k++) {
    const [turn, t] = this.game.spawn("mutant", "hunt")
    t.shotIn = this.game.memory.leftIn(turn)
    this.game.chance.draw()
    const edge = this.game.wrapX(this.game.scroll - this.game.screenWidth)
    let away = this.game.wrapX(this.game.chance.placeOnPlanet() - edge)
    if (away < 600) away = away + 1024
    t.x = this.game.wrapX(away + edge)
    t.y = Math.floor(this.game.chance.last / 2) + 44 + t.y % 1
    this.game.effects.appear(t)
    this.game.director.count("mutants", 1)
    }

// (the arcade compares two places as signed numbers, so a mutant on the other half of
// the planet from the ship may go the long way round)
const ship = this.game.world.ship, speed = this.settings.mutantSpeed / 32, signed = (x) => x >= 1024 ? x - 2048 : x
t.vx = signed(ship.planetX) < signed(t.x) ? -speed : speed
const shipY = ship.py, y = Math.floor(t.y), down = this.mutantDrop(), up = this.game.reverseUpDown(down)
let hops = true
if (this.game.wrapX(ship.planetX - t.x + 380 / 32) > 56) {
    const gap = byte(shipY - y)
    if (shipY > y) t.vy = gap > 8 ? 0 : up
    else t.vy = signed8(gap) > -8 ? down : 0
    }
else {
    t.vy = shipY >= y ? down : up
    hops = t.py != 0
    }
if (hops) {
    const hop = this.game.wrapY(t.y + (this.game.chance.last >= 128 ? this.settings.mutantHop : -this.settings.mutantHop))
    t.y = hop < this.game.top ? this.game.bottom + t.y % 1 : hop
    t.shotIn = countDown(t.shotIn)
    if (t.shotIn == 0) {
        t.shotIn = this.game.chance.upTo(this.settings.mutantShotTime)
        if (this.game.shooters.shoot(t)) this.game.sound("mutant shot")
        }
    }
this.rest(turn, 3, "hunt")

while (!this.game.frozen && !this.nearScreen(t)) {
    t.course = countDown(t.course)
    if (t.course < 128) { this.rest(turn, 10, "away"); return }
    this.newCourse(t)
    t.course = (this.game.chance.last % 16) + 8
    }
t.shotIn = 0
this.wander(turn, t)

const shipY = this.game.world.ship.py
let gap = byte(Math.floor(t.y) - shipY), dodge = false
this.fled = gap
if (gap < 128) {
    if (gap <= 9) { gap = this.mayFire(turn, t, true); if (gap < 0) return }
    dodge = gap < 12
    }
else {
    gap = byte(-gap)
    if (gap <= 12) { gap = this.mayFire(turn, t, false); if (gap < 0) return }
    dodge = gap <= 15
    }
this.point("steer")
if (dodge) {
    const dodge = this.settings.firebomberDodge / 256, speed = this.fled >= 128 ? this.game.reverseUpDown(dodge) : dodge
    t.vy = this.game.pilot.invisible ? speed : 2 * speed
    t.course = (this.game.chance.last % 128) + 30
    }
else {
    t.course = countDown(t.course)
    if (t.course >= 128) { this.newCourse(t); t.course = (this.game.chance.last % 128) + 30 }
    }
this.next(turn, t)

const across = Math.floor(signed8(this.game.chance.third) / 16)
t.vx = (across >= 0 ? across + 10 : across - 10) / 32
t.vy = (this.game.chance.third < 128 ? this.game.chance.third + 80 : this.game.chance.third - 336) / 256

let answer = byte(this.game.director.wave - 1)
if (answer == 0) return 0
if (answer <= 2) {
    this.fled = answer - 1
    answer = this.game.chance.draw()
    if (answer >= 224 || (answer > 128 && this.fled == 0)) { t.shotIn = 255 - this.settings.firebomberShots; return t.shotIn }
    if (answer > 128) answer = 1
    }
if (t.shotIn != 0) return answer
if (t.py == 0) return 0
this.letGo(turn, t, above)
return -1

if (t.kind == "firebomber") this.game.director.count("firebombers", -1)
this.game.award(t.kind == "firebomber" ? 250 : 100)
this.game.sound("fire hit")
const turn = this.game.turnOf(t.turn)
if (turn != null) this.game.end(turn)
this.game.leave(t)
this.game.memory.takeSlot(t.id)
const boom = this.game.begin("boom", "boom")
boom.wreck = t
boom.picture = t.kind == "firebomber" ? "firebomber-burst" : "fireball-burst"
boom.count = 3
return true

const from = this.game.across(t.x + 50)
if (from >= this.game.screenWidth + 100) {
    t.shotIn = 19
    this.rest(turn, 16, "far")
    return
    }
t.frame = t.vx < 0 ? t.frame % 4 + 1 : (t.frame + 2) % 4 + 1
if (t.shotIn != 0) t.shotIn = t.shotIn - 1
t.course = countDown(t.course)
if (t.course == 0) this.veer(t)
this.drifted(turn, t)

let x = 682.65625 * ((this.game.chance.last % 4) == 0 ? 1 : this.game.chance.last % 4)     // a third of the way round, near enough
for (let k = 0; k < count; k++) {
    const gate = this.game.newThing("gate")
    gate.x = x
    gate.y = (this.game.chance.draw() % 32) + 92 + gate.y % 1
    gate.stays = true
    this.game.enter(gate)
    x = this.game.wrapX(x + 640)
    }

t.kept = this.game.planetGone
this.game.halt(["controls", "motion", "ship", "effects", "planet", "touching"])
