if (this.captions < 10) { this.captions = this.captions + 1; this.rest(t, 4, "enemiesNamed"); return }
this.rounds = 29; this.letterAt = 0; this.captionAt = 0
this.enemiesMended(t)

t.step = "enemiesMended"
if (this.captionAt == 9) {
    this.captionAt = 0; this.rounds = this.rounds - 1
    if (this.rounds == 0) { this.logo(t); return }
    }
this.captionAt = this.captionAt + 1
this.rest(t, 4, "enemiesLettered")

if (this.letterAt == 18) {
    this.letterAt = 0; this.captionAt = 0; this.rounds = this.rounds - 1
    if (this.rounds == 0) { this.logo(t); return }
    this.enemiesMended(t)
    return
    }
this.letterAt = this.letterAt + 1
this.rest(t, 2, "enemiesMended")

if (turn.count == 1) { this.game.end(turn); return }
if (t != null && !t.appearing) t.frame = (t.frame + 1) % turn.count
turn.wait = turn.pace

if (this.wait != 0) {
    this.wait = this.wait - 1
    if (this.wait != 0) return
    this.times = this.times - 1
    if (this.times == 0) {
        this.place = this.place + 1
        this.times = this.place < this.tune.length ? this.tune[this.place][0] : 0
        }
    if (this.times != 0) {
        this.wait = this.tune[this.place][1]
        this.send(this.tune[this.place][2])
        return
        }
    this.matters = 0
    }
// nothing is due: the thrust button has the board
if (!thrust) {
    if (this.thrustOn) { this.thrustOn = false; this.send(15) }
    }
else if (!this.thrustOn && flying) { this.thrustOn = true; this.send(22) }

const r = this.rules.find((r) => r.kinds.includes(kind))
if (r == null) throw new Error(`no rules for "${kind}"`)
return r

this.palette = this.palette.map((c, i) => {
    const lit = this.litInks[i]
    if (i == 0) return c
    return c + (this.redOf(lit) > this.redOf(c) ? 1 : 0) + (this.greenOf(lit) > this.greenOf(c) ? 8 : 0)
        + (step % 2 == 0 && this.blueOf(lit) > this.blueOf(c) ? 64 : 0)
    })

this.nextId = this.nextId + 1
this.memory.takeSlot(this.nextId)
return { id: this.nextId, kind: kind, x: 0, y: this.memory.fractionIn(this.nextId), vx: 0, vy: 0, px: 0, py: 0, shown: "none",
    frame: 1, facing: 1, appearing: false, stays: false, turn: 0 }

const turn = this.begin(kind, step), t = this.newThing(kind)
this.link(turn, t)
return [turn, t]

if (this.frozen) return
this.wiped = false
for (const t of this.world.near) {
    if (t.py != 0) {
        if (t.py > to || t.py <= above) continue
        const old = this.shapeOf(t.shown)
        this.rubOut(t.px, t.py, old.wide, old.high)
        t.py = 0
        }
    const py = Math.floor(t.y), picture = this.pictureOf(t), shape = this.shapeOf(picture)
    if (py > to || py <= above) continue
    const across = this.across(t.x)
    if (across >= this.screenWidth) continue
    const px = Math.floor(across)
    if (Math.floor(px / 2) + shape.wide > 156) continue      // past the screen's right edge
    t.px = px; t.py = py
    t.shown = picture
    this.rubOut(px, py, shape.wide, shape.high)
    }

const first = Math.max(0, Math.floor(px / 2)), last = Math.min(Math.floor(px / 2) + wide, 160)
for (const trail of this.world.trails) {
    if (trail.id < py || trail.id >= py + high) continue
    for (let pair = first; pair < last; pair++) { trail.inks[2 * pair] = 0; trail.inks[2 * pair + 1] = 0 }
    }
if (!this.frozen) return
for (const star of this.world.stars) if (star.py >= py && star.py < py + high && star.px >= 2 * first && star.px < 2 * last) star.lit = false
if (!this.planetGone || !this.groundShown) return
const holes = this.world.holes ?? []
for (let row = py; row < py + high; row++) {
    let line = holes.find((h) => h.id == row)
    if (line == null) { line = { id: row, pairs: [] }; holes.push(line) }
    for (let pair = first; pair < last; pair++) if (!line.pairs.includes(pair)) line.pairs.push(pair)
    }
this.world.holes = holes

const mine = this.shapeOf(picture)
for (const t of this.world.near) {
    if (t.py == 0) continue
    const where = this.overlap(px, py, mine, t.px, t.py, this.shapeOf(t.shown))
    if (where == null) continue
    this.impact = where
    return this.rulesFor(t.kind).hit(t, byShip)
    }
return false

const ax = Math.floor(apx / 2), bx = Math.floor(bpx / 2)
for (let x = Math.max(ax, bx); x < Math.min(ax + a.wide, bx + b.wide); x++)
    for (let y = Math.min(ay + a.high, by + b.high) - 1; y >= Math.max(ay, by); y--)
        if (this.solidAt(a, x - ax, y - ay) && this.solidAt(b, x - bx, y - by)) return { px: 2 * x, py: y }
return null

const turn = this.turnOf(t.turn)
if (turn != null) this.end(turn)
this.leave(t)
this.award(points)
this.effects.explode(wreck ?? this.pictureOf(t), t)
this.sound(sound)

const inks = this.$provided("inks"), rings = this.$provided("rings"), along = Math.floor(this.px / 32)
const inner = [8, 8, 7, 6, 5, 4, 3, 2, 1][along] ?? 0
const center = inner + ([5, 5, 5, 4, 3, 3, 2][along] ?? 1)
const ring = (ink, x, y, w, h) => {
    d.fillStyle = arcadeColor(inks[ink])
    d.fillRect(x, y, w, 1); d.fillRect(x, y + h - 1, w, 1)
    d.fillRect(x, y, 1, h); d.fillRect(x + w - 1, y, 1, h)
    }
ring(rings[0], 0, 0, 15, 12)
ring(rings[1], inner, 3, 7, 6)
d.fillStyle = arcadeColor(inks[rings[2]])
d.fillRect(center, 5, 1, 2)

const inks = this.$provided("inks"), top = this.root.game.top
for (const e of [...this.appears, ...this.bursts]) {
    if (!e.drawn) continue
    const shape = this.root.game.shapeOf(e.picture), gap = Math.floor(e.size)
    if (shape.pixels.length == 0) continue
    for (let i = 0; i < shape.wide; i++) {
        const pair = e.cx + gap * (i - e.xof)
        if (pair < 0 || pair > 152) continue
        for (let j = 0; j < shape.high / 2; j++) {
            const y = e.cy + 2 * gap * (j - e.yof)
            if (y < top || y > 255 || (i == e.xof && j == e.yof)) continue
            for (let r = 0; r < 2; r++)
                for (let c = 0; c < 2; c++) {
                    const ink = this.inkAt(shape, 2 * i + c, 2 * j + r)
                    if (ink == 0) continue
                    d.fillStyle = arcadeColor(inks[ink])
                    d.fillRect(2 * pair + c, y + r, 1, 1)
                    }
            }
        }
    }

const across = 2 * shape.wide
if (row < shape.high) return parseInt(shape.pixels[row * across + column], 16)
return column + 2 < across ? parseInt(shape.pixels[column + 2], 16) : 0

const rows = this.root.game.scenery.rows, at = Math.floor(this.$provided("seen").groundAt) + 2048 - this.root.game.pages.groundLag
for (let x = 4; x < 300; x++) this.dot(d, x, rows[(at + x) % 2048], this.root.game.ink.ground)
for (const line of (this.$data(["holes"]) ?? [])) for (const pair of line.pairs) d.clearRect(2 * pair, line.id, 2, 1)

const small = this.root.game.scenery.smallGround, ground = this.$data(["ground"])
if (ground < 0) return
for (let k = 0; k < 64; k++) {
    const g = small[(ground + k) % 64]
    this.pair(d, 88 + 2 * k, g.row, g.top)
    this.pair(d, 88 + 2 * k, g.row + 1, g.bottom)
    }

const inks = this.$provided("inks"), shards = this.$data(["shards"]), lost = this.$data(["lost"])
const block = (x, y, ink) => {
    d.fillStyle = arcadeColor(inks[ink])
    d.fillRect(x, y, 2, 2)
    }
let gone = 0
shards.forEach((s, i) => {
    for (; gone < lost.length && lost[gone].slot <= i; gone++) block(lost[gone].px, lost[gone].py, 0)
    if (!s.moved) return
    block(s.wasPx, s.wasPy, 0)
    block(s.px, s.py, s.ink)
    })
for (; gone < lost.length; gone++) block(lost[gone].px, lost[gone].py, 0)

const out = new Map()
let x = this.px, y = this.py, big = this.font == "large", color = this.ink, blanking = this.zeros, margin = this.px
const column = (at, rows, high) => {
    for (let r = 0; r < high; r++) out.set(`${at},${y + r}`, [at, y + r, Math.floor(rows / 2 ** r) % 2 == 1 ? color : 0])
    }
const letter = (ch) => {
    const i = art.order.indexOf(ch)
    if (!big) {
        if (i < 0) return
        x = x + x % 2
        art.small[i].columns.forEach((rows, k) => column(x + k, rows, 5))
        x = x + art.small[i].step
        return
        }
    const g = art.large[i < 0 ? 10 : i]
    if (x % 2 == 1) column(x - 1, 0, 7)
    g.columns.forEach((rows, k) => column(x + k, rows, 7))
    if ((x + g.wide) % 2 == 1) column(x + g.wide, 0, 7)
    x = x + g.step
    }
// a number's digits: the last is always printed
const count = (figures) => {
    let begun = false
    for (let k = 0; k < figures.length; k++) {
        if (figures[k] == "0" && !begun && blanking != "shown" && k < figures.length - 1) {
            if (blanking == "spaced") x = x + (big ? 6 : 4)
            continue
            }
        begun = true
        letter(figures[k])
        }
    }
for (const p of this.said()) {
    if (p.ink != null) color = p.ink
    else if (p.scanner) color = this.frameInk
    else if (p.at != null) { x = p.at[0]; y = p.at[1] }
    else if (p.move != null) { x = x + p.move[0]; y = y + p.move[1] }
    else if (p.font != null) { if (big != (p.font == "large")) { big = !big; y = y + (big ? -2 : 2) } }
    else if (p.zeros != null) blanking = p.zeros
    else if (p.figures == 4) count(String((this.long >= 0 ? this.long : this.number) % 10000).padStart(4, "0"))
    else if (p.figures == 2) count(String(this.number % 100).padStart(2, "0"))
    else if (p.digits != null) count(p.digits)
    else if (p.line != null) {
        if (p.line != "return") y = y + (big ? 9 : 7)
        if (p.line != "feed") x = margin
        }
    else if (p.margin) margin = x
    else if (p.text != null) for (const ch of p.text) letter(ch)
    }
return [...out.values()]

const inks = this.$provided("inks")
d.fillStyle = arcadeColor(inks[this.ink])
for (const [x, y, w, h] of this.lines) d.fillRect(x, y, w, h)
d.fillStyle = arcadeColor(inks[this.marks])
for (const [x, y, w, h] of this.ticks) d.fillRect(x, y, w, h)

const out = []
if (a == null) return out
let drawn = 0
for (const w of a.word) {
    let x = this.left + w.at
    for (const [times, runs] of (a.letters)[w.letter]) {
        for (let k = 0; k < times; k++) {
            let y = this.row, lit = false
            for (const run of runs) {
                if (lit) for (let r = 0; r < run; r++) out.push([drawn, x, y + r, w.ink])
                y = y + run; lit = !lit
                }
            drawn = drawn + 1; x = x + 1
            }
        }
    }
return out

if (lit.length == 0) return []
const at = (x, y) => `${x},${y}`
const on = new Set(lit.map((p) => at(p[1], p[2])))
const marks = new Map()
const mark = (x, y, upright) => {
    if (!on.has(at(x, y))) return
    const m = marks.get(at(x, y)) ?? [x, y, 0, 0]
    m[upright ? 2 : 3] = 1
    marks.set(at(x, y), m)
    }
const xs = lit.map((p) => p[1]), ys = lit.map((p) => p[2])
const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys)
for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) {
    if (!on.has(at(x, y))) continue
    if (!on.has(at(x, y - 1))) { mark(x, y, true); mark(x, y + 1, true) }
    if (!on.has(at(x, y + 1))) { mark(x, y, true); mark(x, y - 1, true) }
    if (!on.has(at(x - 1, y))) { mark(x, y, false); mark(x + 1, y, false) }
    if (!on.has(at(x + 1, y))) { mark(x, y, false); mark(x - 1, y, false) }
    }
return [...marks.values()]

const pairs = Math.min(this.outlined, 136), halfRows = Math.max(0, this.outlined - 136)
if (upright == 1 && Math.floor(x / 2) < Math.floor(this.left / 2) + pairs) return true
if (across == 0) return false
const rows = Math.floor(halfRows / 2)
return y - this.row < rows || (y - this.row == rows && halfRows % 2 == 1 && Math.floor(x / 2) < 75)

for (const p of this.pixels) {
    if (p[0] >= this.columns) break
    d.fillStyle = arcadeColor(this.colors[p[3]])
    d.fillRect(p[1], p[2], 1, 1)
    }
if (this.outlined == 0) return
d.fillStyle = arcadeColor(this.colors[this.root.game.ink.outline])
for (const e of this.edges) if (this.traced(e[0], e[1], e[2], e[3])) d.fillRect(e[0], e[1], 1, 1)

scripts.src:
 const STAGES = ["idle", "touching", "effects", "chance", "presses", "turns", "done"];
function stageAt(s) { return STAGES.indexOf(s); }
;
;
;function signed8(v) { const b = (v % 256 + 256) % 256; return b < 128 ? b : b - 256; }
function signed16(v) { const w = (v % 65536 + 65536) % 65536; return w < 32768 ? w : w - 65536; }
function byte(v) { return (v % 256 + 256) % 256; }
function word(v) { return (v % 65536 + 65536) % 65536; }
function countDown(n) { return byte(n - 1); }
function rgb(red, green, blue) { return red + 8 * green + 64 * blue; }
;function arcadeColor(byte) {
    const ladder = (level, ohms) => {
        const g = ohms.map((r) => 1 / r), all = g.reduce((a, b) => a + b, 0);
        return Math.round(255 * g.reduce((a, gi, i) => a + (Math.floor(level / 2 ** i) % 2) * gi, 0) / all);
    };
    const red = byte % 8, green = Math.floor(byte / 8) % 8, blue = Math.floor(byte / 64);
    return ladder(red, [1200, 560, 330]) * 65536 + ladder(green, [1200, 560, 330]) * 256 + ladder(blue, [560, 330]);
}
;function wallClock() { return performance.now(); } /*$b*/ return { STAGES, stageAt, signed8, signed16, byte, word, countDown, rgb, arcadeColor, wallClock };

methods.body:
this.root.restCursor()
if (e.repeat || e.meta || e.ctrl || e.alt) return
if (this.root.paused && !this.root.game.gameOver) { this.root.paused = false; this.root.heldBack = e.code; return }
if (e.code == "Escape" && !this.root.game.gameOver) { this.root.paused = true; return }
if ((e.code == "Enter" || e.code == "Space") && this.root.game.gameOver) { this.root.heldBack = e.code; this.root.game.start() }
if (e.code == "F2") this.root.timing = !this.root.timing

const started = wallClock()
for (let n = this.gameFrames(dt); n > 0; n--) this.root.game.step(this.root.controls())
if (this.root.timing) this.root.meter.add(dt * 1000, wallClock() - started)

if (this.frameTime == 0) this.frameTime = dt
else if (dt < 1.5 * this.frameTime) this.frameTime = 0.95 * this.frameTime + 0.05 * dt
const per = Math.max(1, Math.round(this.period / this.frameTime))
if (Math.abs(per * this.frameTime - this.period) <= 0.05 * this.period) {
    this.shown = this.shown + Math.max(1, Math.round(dt / this.frameTime))
    const n = Math.floor(this.shown / per)
    this.shown = this.shown - n * per
    return n
    }
this.banked = this.banked + dt
const n = Math.floor(this.banked / this.period)
this.banked = this.banked - n * this.period
return n
